head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > useEdit]<br/>컴포넌트의 라벨 표시 영역에 편집 기능을 활성화 할지 설정합니다.",
    "validation" : [            
        "useItemLocale 속성으로 라벨값에 다국어가 적용된 경우 적용된 다국어에 맞게 입력하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();
    }    

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    let properties = {
        useEdit : true,
        useLocale : true,
        useItemLocale : true,         
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="라벨에 다국어 적용된 상태"', '', 'label1');

    strTarget += '<xf:checkcombobox ' + strNameSpace + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_Item">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:checkcombobox>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "checkcombobox",
        strTarget,
        grp_comp
    );
}



scwin.btn_getItemInfo_onclick = function (e) {   
    // 해당 class를 가진 모든 input 요소를 선택
    let checkboxElements = document.querySelectorAll('input.w2table_ccb_col_checkbox');

    if (checkboxElements.length == 0)
            wf_body_bottom.getObj("scwin").setReturnValue("checkcombobox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    // 각각의 체크박스 요소의 checked 속성 값을 출력
    for (var i = 0; i < checkboxElements.length; i++) {
        let isChecked = checkboxElements[i].checked; // checked 속성 값 가져오기
        wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" checked : " + isChecked);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" index : " + target1.getInfo(i).index);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" label : " + target1.getInfo(i).label);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" value : " + target1.getInfo(i).value);  
    }
}
